const LATENCY_THRESHOLD_MS = 300;

function decide(trace) {
  // trace = { spans: [{ durationMs, error }], baseKeep: boolean }
  const hasError = trace.spans.some(s => s.error);
  const isSlow = trace.spans.some(s => s.durationMs >= LATENCY_THRESHOLD_MS);
  return trace.baseKeep;
}

