// head-based sampler, called once at the root span
let counter = 0;
const RATE = 0.1; // keep ~10%

function shouldSample(traceId) {
  counter++;
  return counter % 10 === 0;        // every 10th trace
}

// downstream services re-run shouldSample with their own counter
function childShouldSample(traceId) {
  return shouldSample(traceId);
}
